// node2 - sensor node

// SYSCLK   = 16MHz
// HCLK     = 16MHz (SYSCLK / AHB prescaler(=1))
// PCLK2    = 16MHz (HCLK / APB2 prescaler(=1))

#include <stdint.h>
#include "uart.h"
#include "sht20.h"
#include "delay.h"
#include "speed_sensor.h"
#include "can.h"

static volatile uint32_t speed_send_fail_count = 0U;
static volatile uint32_t temperature_send_fail_count = 0U;

void enable_fpu(void)
{
    *(volatile uint32_t*)0xE000ED88U |= (0xFU << 20);
}

int main(void)
{
    enable_fpu();

    sht20_init();
    speed_sensor_init();
    can1_init();

    while(1)
    {
        uint16_t speed = speed_sensor_get_kmh();
        float temperature = sht20_measure_temperature();

        if(node2_send_vehicle_speed((uint8_t)speed) == 0)
        {
            speed_send_fail_count++;
        }

        if(node2_send_temperature(temperature) == 0)
        {
            temperature_send_fail_count++;
        }
    }
}